    if (adcs_quat_normalize(sh_input.q_bi, &norm_q) == ADCS_OK) {
        adcs_quat_t aligned;
        adcs_quat_t inv_last;
        adcs_quat_t rel;
        double d_abs;

        /* sign closest to last published attitude: use |dot| */
        d_abs = adcs_quat_abs_dot(&norm_q, &sh_state.last_q_bi);
        if ((norm_q.w * sh_state.last_q_bi.w
             + norm_q.x * sh_state.last_q_bi.x
             + norm_q.y * sh_state.last_q_bi.y
             + norm_q.z * sh_state.last_q_bi.z) < 0.0) {
